candidates.raw:
    if ((requested == NULL) || (area_turns == NULL) || (resistance == NULL) || 
        (voltage_limit == NULL) || (voltage == NULL) || (realized == NULL) || (mask == NULL)) {
        return ADCS_E_NULL;
    }

    // Initialize outputs to zero as per "failures zero" contract requirement
    voltage->x = 0.0; voltage->y = 0.0; voltage->z = 0.0;
    realized->x = 0.0; realized->y = 0.0; realized->z = 0.0;
    *mask = 0U;

    size_t i;
    for (i = 0; i < 3; i++) {
        // Validate inputs: area_turns and resistance must be positive, voltage_limit non-negative
        if (area_turns[i] <= 0.0 || resistance[i] <= 0.0) {
            return ADCS_E_RANGE;
        }
        if (voltage_limit[i] < 0.0) {
            return ADCS_E_RANGE;
        }
    }

    for (i = 0; i < 3; i++) {
        double raw_voltage;
        double v_clamped;
        double r_dipole;

        // Raw voltage calculation: R * I = V => V = R * (D/A)
        // Dipole m = NIA => I = m / NA. So V = R * m / NA.
        raw_voltage = resistance[i] * requested[i] / area_turns[i];

        // Voltage bound: +/- limit
        v_clamped = ADCS_CLAMP(raw_voltage, -voltage_limit[i], voltage_limit[i]);

        // Mask bit set on clipping (strict exceedance implies raw was outside bounds)
        if (v_clamped != raw_voltage) {
            *mask |= (unint32)(1u << i);
        }

        // Realized dipole: m = V * NA / R
        r_dipole = v_clamped * area_turns[i] / resistance[i];

        if (i == 0) {
            voltage->x = v_clamped;
            realized->x = r_dipole;
        } else if (i == 1) {
            voltage->y = v_clamped;
            realized->y = r_dipole;
        } else {
            voltage->z = v_clamped;
            realized->z = r_dipole;
        }
    }

    return ADCS_OK;
}

