candidates.raw:
    if (requested == NULL || area_turns == NULL || resistance == NULL || voltage_limit == NULL ||
        voltage == NULL || realized == NULL || mask == NULL) {
        return ADCS_E_NULL;
    }

    for (int i = 0; i < 3; ++i) {
        if (!isfinite(area_turns[i]) || !isfinite(resistance[i]) || !isfinite(voltage_limit[i])) {
            return ADCS_E_RANGE;
        }
        if (area_turns[i] <= 0.0 || resistance[i] <= 0.0) {
            return ADCS_E_RANGE;
        }
        if (voltage_limit[i] < 0.0) {
            return ADCS_E_RANGE;
        }
    }

    if (!isfinite(requested->x) || !isfinite(requested->y) || !isfinite(requested->z)) {
        return ADCS_E_RANGE;
    }

    double raw_v[3];
    double lim_v[3];
    double real_dip[3];
    unint32 mask_val = 0U;

    for (int i = 0; i < 3; ++i) {
        double req = 0.0;
        if (i == 0) req = requested->x;
        else if (i == 1) req = requested->y;
        else req = requested->z;

        raw_v[i] = resistance[i] * req / area_turns[i];

        if (fabs(raw_v[i]) > voltage_limit[i]) {
            lim_v[i] = copysign(voltage_limit[i], raw_v[i]);
            mask_val |= (unint32)(1U << i);
        } else {
            lim_v[i] = raw_v[i];
        }

        real_dip[i] = lim_v[i] * area_turns[i] / resistance[i];
    }

    voltage->x = lim_v[0];
    voltage->y = lim_v[1];
    voltage->z = lim_v[2];

    realized->x = real_dip[0];
    realized->y = real_dip[1];
    realized->z = real_dip[2];

    *mask = mask_val;

    return ADCS_OK;
}

